
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_mgga_k_csk_loc1_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("mgga_k_csk_loc1", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([3.107510759261062e+01, 3.313352621259359e+01, 3.541848182276672e+01, 3.760964877655102e+01, 3.915895776094038e+01, 3.937145091968911e+01, 3.768839298768919e+01, 3.411543688773061e+01, 2.942396142147767e+01, 2.450810043559550e+01, 1.960165005777993e+01, 6.543081448205671e+00, 1.296864145538449e+00, 1.226754209658684e+00, 1.081676036615816e+00, 9.217537006710258e-01, 8.548121234238838e-01, 8.272485695557434e-01, 8.156770560801927e-01, 8.126908623944100e-01]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


